namespace dyng::detail {

std::uint64_t triad_count_sequential(array_view<const std::int64_t> row_ptr) {
  // TODO(triad_count): the static count. The placeholder: the incidences.
  return row_ptr.empty() ? 0 : static_cast<std::uint64_t>(row_ptr[row_ptr.size() - 1]);
}

}  // namespace dyng::detail
